import{z as s,x as p,o as E,c as d,q as o,j as A,D as e,d as t,s as B,S as i,b as l}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"过拟合、权重衰减与早停","description":"","frontmatter":{"title":"过拟合、权重衰减与早停","date":"2026-09-10T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/overfit-wd-earlystop.md","filePath":"llm/overfit-wd-earlystop.md","lastUpdated":1791063341000}'),n={name:"llm/overfit-wd-earlystop.md"};function m(h,a,D,c,u,C){const r=p("Mermaid");return E(),d("div",null,[a[2]||(a[2]=o('<h1 id="过拟合、权重衰减与早停" tabindex="-1">过拟合、权重衰减与早停 <a class="header-anchor" href="#过拟合、权重衰减与早停" aria-label="Permalink to &quot;过拟合、权重衰减与早停&quot;">​</a></h1><div class="epigraph"><p>当验证损失开始上升，继续沿着训练损失走就是在记样本；停下来，或把参数往回拉，是同一问题的两种时间尺度。</p><footer>—— 据 Srivastava et al., Dropout, JMLR 2014；Loshchilov &amp; Hutter, Decoupled Weight Decay Regularization, ICLR 2019；Prechelt, Early Stopping, 1998 整理</footer></div><p><a href="/llm/val-gen-gap">验证集与泛化缺口</a>给出 \\(L_{\\mathrm{train}}\\) 与 \\(L_{\\mathrm{val}}\\) 分叉的读法。本课不重划分。缺口是：分叉之后做什么。方法有三条常用杠杆——早停、权重衰减、以及稍后才细讲的 Dropout。本课把前两条钉在优化循环里；Dropout 留在前馈单元末课，避免和注意力掩码混在一起。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>缺口扩大，说明当前 \\(\\theta\\) 正在拟合训练集的特异结构。若容量远大于数据，经验风险可以继续降，期望风险升高。优化器没有义务在「真规律」处停下，因为它看不见 \\(R\\)。缺口因此不是再换损失的代数形式，而是在更新规则或停止时间上加约束，使路径不要走得太远。</p><p><span class="marginnote">术语翻译：「泛化缺口」就是训练损失与验证损失的差。它像模拟考与高考的分数差：模拟考（训练集）分越高、高考（验证集）分反而越低，说明你在背模拟考的原题，而不是在学方法。</span></p><p>早停：监视 \\(L_{\\mathrm{val}}\\)，在它不再改善后若干步，取历史上验证最好的检查点。权重衰减：在损失里加 \\(\\frac{\\lambda}{2}\\|\\theta\\|_2^2\\)，或在更新里减 \\(\\eta\\lambda\\theta\\)（与 Adam 解耦的 AdamW）。两者都在限制 \\(\\theta\\) 离开原点或离开早先较好的区域，但一个作用在时间上，一个作用在范数上。</p><h3 id="权重衰减不是学习率变小" tabindex="-1">权重衰减不是学习率变小 <a class="header-anchor" href="#权重衰减不是学习率变小" aria-label="Permalink to &quot;权重衰减不是学习率变小&quot;">​</a></h3><p>\\(\\eta\\) 缩小让每一步都短，训练与验证的拟合都会变慢。\\(\\lambda\\) 把参数往 \\(0\\) 拉，对大权重惩罚更重，改变的是可到达的假设集合，而不只是速度。把衰减写进 Adam 的梯度里，会被二阶矩缩放，有效 \\(\\lambda\\) 随坐标而变，不再是「全体参数同一 \\(\\ell_2\\) 罚」。AdamW 把 \\(\\theta\\leftarrow\\theta-\\eta\\lambda\\theta\\) 放在自适应步之后，才接近经典权重衰减。调 \\(\\eta\\) 代替调 \\(\\lambda\\)，缺口对不上。</p><p><span class="marginnote">直觉类比：调小 \\(\\eta\\) 像开车轻踩油门——哪儿都能去，只是都到得慢；调大 \\(\\lambda\\) 像给某些街区限行——大权重区域根本去不了。前者的解集合不变，后者的解集合被缩小，这正是「衰减不是学习率变小」的含义。</span></p><p><span class="marginnote">早停依赖验证集，因此对验证有轻度过拟合。权重衰减不看验证，但 \\(\\lambda\\) 本身仍要用验证来选。没有「完全不碰验证的正则」，只有「不要用测试集选 \\(\\lambda\\)」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>训练循环里同时记录：当前 \\(\\theta\\)、验证指标、最佳检查点。早停耐心（patience）用步数而不是 epoch 声明，因为大语料上一个 epoch 极长。权重衰减系数 \\(\\lambda\\) 与 \\(\\eta\\) 一起报；改批量大小时，\\(\\lambda\\) 是否缩放要与更新规则一致。偏置与归一化增益有时不衰减，以免把尺度自由度一并罚掉——这是实现惯例，本课允许，但不把例外写成新理论。</p>',13)),(E(),A(i,null,{default:e(()=>[B(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20UPD%5B%22%E5%8F%82%E6%95%B0%E6%9B%B4%E6%96%B0%22%5D%20--%3E%20TR%5B%22%E8%AE%AD%E7%BB%83%E6%8D%9F%E5%A4%B1%E4%B8%8B%E9%99%8D%22%5D%0A%20%20UPD%20--%3E%20VA%5B%22%E9%AA%8C%E8%AF%81%E6%8D%9F%E5%A4%B1%22%5D%0A%20%20VA%20--%3E%7C%22%E4%BB%8D%E9%99%8D%22%7C%20CONT%5B%22%E7%BB%A7%E7%BB%AD%22%5D%0A%20%20VA%20--%3E%7C%22%E4%B8%8A%E5%8D%87%22%7C%20ES%5B%22%E6%97%A9%E5%81%9C%E5%9B%9E%E6%BB%9A%E5%88%B0%E6%9C%80%E4%BD%B3%E6%A3%80%E6%9F%A5%E7%82%B9%22%5D%0A%20%20WD%5B%22%E6%9D%83%E9%87%8D%E8%A1%B0%E5%87%8F%E6%8B%89%E5%90%91%E5%8E%9F%E7%82%B9%22%5D%20--%3E%20UPD%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l("h2",{id:"机制",tabindex:"-1"},[t("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=l("p",null,"过拟合是容量与数据相对关系的现象，不是某一层写错。同一模型在更多数据上可以不过拟合；同一数据上更宽更深更容易过拟合。早停把有效容量变成「训练了多久」：停得早，相当于没用满后期那些能记样本的自由度。权重衰减则让小范数解更受偏好；在线性模型里这对应岭回归，在深度网里它更像一种尺度约束，与后面残差、LayerNorm 的尺度互动。",-1)),(E(),A(i,null,{default:e(()=>[B(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20ES%5B%22%E6%97%A9%E5%81%9C%3A%20%E4%BD%9C%E7%94%A8%E5%9C%A8%E6%97%B6%E9%97%B4%E8%BD%B4%22%5D%0A%20%20%20%20T0%5B%22%E5%88%9D%E6%9C%9F%3A%20%E5%AD%A6%E7%9C%9F%E8%A7%84%E5%BE%8B%22%5D%20--%3E%20T1%5B%22%E4%B8%AD%E6%9C%9F%3A%20%E9%AA%8C%E8%AF%81%E6%9C%80%E5%A5%BD%E7%82%B9%22%5D%20--%3E%20T2%5B%22%E5%90%8E%E6%9C%9F%3A%20%E8%AE%B0%E6%A0%B7%E6%9C%AC%E7%89%B9%E5%BC%82%E7%BB%93%E6%9E%84%22%5D%0A%20%20%20%20T1%20-.%20%22%E5%9B%9E%E6%BB%9A%E5%8F%96%E6%A3%80%E6%9F%A5%E7%82%B9%22%20.-%3E%20BEST%5B%22%E6%9C%80%E4%BD%B3%E9%AA%8C%E8%AF%81%E6%A3%80%E6%9F%A5%E7%82%B9%22%5D%0A%20%20end%0A%20%20subgraph%20WD%5B%22%E6%9D%83%E9%87%8D%E8%A1%B0%E5%87%8F%3A%20%E4%BD%9C%E7%94%A8%E5%9C%A8%E8%8C%83%E6%95%B0%E8%BD%B4%22%5D%0A%20%20%20%20P0%5B%22%E5%8F%82%E6%95%B0%E7%A9%BA%E9%97%B4%22%5D%20--%3E%20P1%5B%22%CE%BB%20%E6%8A%8A%20%CE%B8%20%E5%BE%80%E5%8E%9F%E7%82%B9%E6%8B%89%22%5D%20--%3E%20P2%5B%22%E5%A4%A7%E8%8C%83%E6%95%B0%E8%A7%A3%E8%A2%AB%E6%8E%92%E9%99%A4%22%5D%0A%20%20end%0A%20%20ES%20--%3E%20GAP%5B%22%E6%B3%9B%E5%8C%96%E7%BC%BA%E5%8F%A3%E6%94%B6%E7%AA%84%22%5D%0A%20%20WD%20--%3E%20GAP%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=o('<p><span class="marginnote">常见误区：初学者常把 patience（耐心）理解成「等几个 epoch 再停」。大语料上一个 epoch 要几万步，等一个 epoch 早就冲过最佳点很远。本文强调用<strong>步数</strong>声明耐心，比如 patience = 2000 步：验证损失连续 2000 步没有新低才回滚。</span></p><p>Dropout 稍后会在前向上随机关掉单元，迫使表示冗余。它与权重衰减可叠加，不是替代。本课不把三种杠杆比出唯一赢家；验证曲线才是裁判。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲数据增强、标签平滑的完整菜单，也不把 Dropout 公式写完。下一单元转入<a href="/llm/chain-rule-graph">链式法则与计算图</a>：优化要用的梯度从哪来。后课默认：训练必有验证监视；过拟合时先看早停与 \\(\\lambda\\)，再谈改结构。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>过拟合表现为训练损失仍降、验证损失升；优化器不会自动停在泛化最好处。</li><li>早停用验证历史回滚；权重衰减用范数约束可到达的 \\(\\theta\\)。</li><li>衰减不是把 \\(\\eta\\) 改小；与 Adam 合用应对齐 AdamW 的解耦写法。</li><li>Dropout 是第三条杠杆，本课不展开。</li><li>出处：Prechelt, 1998；Loshchilov &amp; Hutter, ICLR 2019；Srivastava et al., JMLR 2014。</li></ul>',6))])}const _=s(n,[["render",m]]);export{f as __pageData,_ as default};
